item.description:
+++ author = &ldquo;alan&rdquo; categories = [&ldquo;nerd&rdquo;, &ldquo;elixir&rdquo;, &ldquo;machine learning&rdquo;, &ldquo;advocacy&rdquo;] date = &ldquo;2017-01-01T23:37:35-04:00&rdquo; description = &ldquo;My goals as a nerd, in 2017&rdquo; featured = &quot;&quot; featuredalt = &quot;&quot; featuredpath = &quot;&quot; linktitle = &quot;&quot; title = &ldquo;2017 nerd goals&rdquo;
+++
Personal Nerd Goals publish - rejuvinate a history of developer advocacy learn elixir - build a couple of projects from a couple of angles learn machine learning basics

I added an update to CakePHP Book: beforeSave()
Also, if you add a primary key which would turn an “insert” into an “update” within beforeSave() you’ll need to set $this-&gt;__exists = true;… the call to $this-&gt;exists(); happens in model.php before the callback to beforeSave().
if (!isset($this-&amp;gt;data[$this-&amp;gt;name]['id']) &amp;&amp; isset($this-&amp;gt;data[$this-&amp;gt;name]['unique_field'])) { $found = $this-&amp;gt;find(&quot;first&quot;,array( &quot;recursive&quot; =&amp;gt; -1, &quot;fields&quot; =&amp;gt; array(&quot;id&quot;), &quot;conditions&quot; =&amp;gt; array(&quot;unique_field&quot; =&amp;gt; $this-&amp;gt;data[$this-&amp;gt;name]['unique_field']))); if (!empty($found) &amp;&amp; isset($found[$this-&amp;gt;name]['id'])) { $this-&amp;gt;id = $this-&amp;gt;data[$this-&amp;gt;name]['id'] = $found[$this-&amp;gt;name]['id']; &lt;strong&gt;$this-&amp;gt;__exists = true;&lt;/strong&gt; } } return parent::beforeSave(); }
